import {DAYS,WEEKS,GUIDES,DAILY_FIELDS,WEEKLY_FIELDS,SOURCE_RULES,formatDate,today,complete} from './content.js?v=2';
import * as storage from './store.js?v=2';
import {weekStart,addDays,weekLabel,normalizeWord,validDate} from './sync-core.js?v=2';
import {openImageExport} from './export-image.js?v=2';

const $=(q,el=document)=>el.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',book:'M12 5c-3-2-7-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1zm0 0v15',note:'M14 3H4v18h16V9m-6-6 6 6h-6zm-6 9h8m-8 4h6',check:'M8 3H4v18h16V3h-4M9 2h6v4H9zm-2 11 3 3 7-7',settings:'M4 5h16M4 12h16M4 19h16M8 3v4m8 3v4m-8 3v4',arrow:'M4 12h16m-6-6 6 6-6 6',plus:'M12 4v16M4 12h16',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',close:'M5 5l14 14M5 19 19 5',chevron:'m9 5 7 7-7 7',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',print:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4zm8 5v3',menu:'M4 6h16M4 12h16M4 18h16',upload:'M12 17V3m-5 5 5-5 5 5M4 17v4h16v-4',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.note}"/></svg>`;
const S={notes:[],settings:{},route:'home',id:'',draft:null,status:'saved',error:'',query:'',filter:'all',typeFilter:'all',guideQuery:'',ready:false,ref:'reading',referenceOpen:true,terms:[],user:null,month:today().slice(0,7),selectedDate:today(),termQuery:'',termFilter:'all'};
let saveTimer,readTimer,toastTimer,saveQueue=Promise.resolve(),printTitle;
const app=$('#app');
const QA=location.hostname==='127.0.0.1'&&new URLSearchParams(location.search).has('qa');
let qaFail=false;
$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main')?.focus();});
const noteTitle=n=>n.title?.trim()||(n.type==='weekly'?weekLabel(n.weekStart||weekStart(n.date))+' 주간 회고':'제목 없는 스크랩');
const sorted=()=>[...S.notes].sort((a,b)=>b.updatedAt-a.updatedAt);
const guideBy=id=>GUIDES.find(g=>g.id===id)||GUIDES[0];
const weekForDate=date=>{const i=DAYS.indexOf(date);return i>=0?Math.floor(i/5)+1:1;};
const dayForDate=date=>DAYS.indexOf(date)+1;
const routeLink=(route,id='')=>`#${route}${id?'/'+encodeURIComponent(id):''}`;
const statusLabel=()=>({saving:'서버에 저장 중…',saved:'서버 저장 완료',local:'이 기기에 임시 저장 · 동기화 대기',error:'동기화 대기 · 다시 시도해 주세요',pending:'입력 중 · 저장 대기',conflict:'다른 기기 변경 확인 필요',account:'계정을 다시 확인해 주세요'}[S.status]||'동기화 확인 중');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function go(route,id=''){const hash=routeLink(route,id);if(location.hash===hash)render();else location.hash=hash;}
function navItem(route,label,i){const active=S.route===route||(route==='notes'&&S.route==='note')||(route==='tracker'&&S.route==='challenge');return `<a class="nav-link ${active?'active':''}" href="${routeLink(route)}" ${active?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${active?'<span class="nav-dot"></span>':''}</a>`;}
function shell(){
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#home"><span class="brand-mark">${icon('note')}</span><span>경제신문읽기<span class="brand-sub">매일 읽고, 나의 언어로</span></span></a><div class="sidebar-caption">MY READING SPACE</div><nav aria-label="주 메뉴">${navItem('home','홈','home')}${navItem('guide','가이드북','book')}${navItem('notes','스크랩노트','note')}${navItem('tracker','기록 달력','check')}${navItem('glossary','나의 용어장','book')}</nav><div class="sidebar-footer"><div class="small-quote">열심히 하지 마세요.<br><strong>꾸준히 하세요.</strong><span>— 스크랩노트 원문</span></div>${navItem('settings','동기화 · 백업','settings')}<div class="private-note">${icon('lock')} 계정별 비공개 기록</div></div></aside><div class="workspace"><header class="topbar"><span class="topbar-title">읽고, 나의 언어로.</span><a class="sync-pill" id="sync-pill" href="#settings" aria-live="polite">${syncLabel()}</a><a class="top-new button small primary" href="#new/daily">${icon('plus')}<span>새 노트</span></a></header><div id="sync-alert">${syncAlert()}</div>${S.error?`<div class="global-error" role="alert">${esc(S.error)} <button data-action="reconnect">다시 연결</button></div>`:''}<main id="main" tabindex="-1"></main><footer class="page-footer"><span>경제신문읽기 · 오늘의 기록은 내일의 시선</span><span>${esc(S.user?.email||'')} · 계정별 동기화</span></footer></div><nav class="mobile-nav" aria-label="모바일 주 메뉴">${navItem('home','홈','home')}${navItem('guide','가이드','book')}${navItem('notes','노트','note')}${navItem('tracker','달력','check')}${navItem('glossary','용어장','book')}${navItem('settings','설정','settings')}</nav>`;
 const main=$('#main');
 if(S.route==='home')main.innerHTML=home();else if(S.route==='guide')main.innerHTML=guidePage();else if(S.route==='notes')main.innerHTML=notesPage();else if(S.route==='note')main.innerHTML=editor();else if(S.route==='tracker')main.innerHTML=calendarPage();else if(S.route==='challenge')main.innerHTML=tracker();else if(S.route==='glossary')main.innerHTML=glossaryPage();else if(S.route==='settings')main.innerHTML=settingsPage();else main.innerHTML=empty('페이지를 찾을 수 없어요.','홈에서 다시 시작해 주세요.','홈으로','#home');
 if(QA)main.insertAdjacentHTML('beforeend',`<aside class="app-notice qa-controls"><strong>로컬 기능 검증 · 배포본에는 표시되지 않음</strong><button class="button outline small" data-action="qa-failure">${qaFail?'저장 실패 재현 끄기':'저장 실패 재현 켜기'}</button><span role="status">${qaFail?'저장 실패 재현 중':'정상 저장 모드'}</span></aside>`);
 bindPage();bindFeatures();
}
const empty=(title,desc,label,url)=>`<div class="empty-state">${icon('note')}<h2>${title}</h2><p>${desc}</p>${label?`<a class="button primary" href="${url}">${label}${icon('arrow')}</a>`:''}</div>`;
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function noteCard(n){return `<a class="note-card" href="#note/${encodeURIComponent(n.id)}"><div class="card-kicker"><span>${n.type==='weekly'?'WEEKLY REFLECTION':'DAILY SCRAP'}</span><span class="badge ${complete(n)?'green':''}">${n.type==='weekly'?'주간 회고':complete(n)?'필수 3칸 작성':'작성 중'}</span></div><h3>${esc(noteTitle(n))}</h3><p class="note-excerpt">${esc(n.type==='weekly'?(n.keywords||n.memorable||'이번 주를 돌아보는 나의 기록'):(n.what||'기사 한 개, 나의 언어로 시작해 보세요.'))}</p><div class="card-meta"><span>${n.type==='weekly'?weekLabel(n.weekStart||weekStart(n.date)):formatDate(n.date)}</span><span>${esc(n.paper||'')}${icon('arrow')}</span></div></a>`;}
function dayStrip(){const days=Array.from({length:7},(_,i)=>addDays(today(),i-6));return `<div class="day-strip week-strip" aria-label="최근 7일 기록 현황">${days.map(d=>{const notes=S.notes.filter(n=>n.type==='daily'&&n.date===d);return `<button class="day-tile ${d===today()?'today':''} ${notes.length?'written':''}" data-action="calendar-day" data-date="${d}" aria-label="${formatDate(d)} 기록 ${notes.length}개"><span>${Number(d.slice(8))}</span><small>${['일','월','화','수','목','금','토'][new Date(d+'T12:00:00').getDay()]}</small>${notes.length?'<span class="day-tick">·</span>':''}</button>`;}).join('')}</div>`;}
function home(){const recent=sorted().slice(0,3),read=S.settings.reading,g=guideBy(read?.guide||'rules'),monthNotes=S.notes.filter(n=>n.type==='daily'&&n.date.startsWith(today().slice(0,7))),days=new Set(monthNotes.map(n=>n.date)).size;
 return `<section class="home-hero"><div class="hero-text"><div class="eyebrow"><span class="tiny-dot"></span> 하루 한 기사, 나를 위한 세 줄</div><h1>세상을 읽고,<br><span>생각을 남기는 시간.</span></h1><p>챌린지가 끝나도, 나의 기록은 계속됩니다.<br>오늘의 경제신문을 한 줄씩 남겨보세요.</p><div class="hero-actions"><button class="button primary" data-action="day-note" data-date="${today()}">${icon('plus')} 오늘의 스크랩 쓰기</button><a class="text-link" href="#guide">가이드북 읽기 ${icon('arrow')}</a></div></div><div class="hero-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="paper-back"></div><div class="paper-art"><div class="paper-head">THE DAILY READING <span>EVERY DAY</span></div><div class="paper-title">작은 기록이 만드는<br>커다란 시선.</div><div class="paper-lines"><i></i><i></i><i></i></div><div class="paper-questions"><span>WHAT <b>무슨 일이?</b></span><span>WHY <b>왜 그랬을까?</b></span><span>SO WHAT <b>그래서 어떻게?</b></span></div><div class="paper-stamp">읽고<br>기록하기</div></div><span class="art-spark">✳</span></div></section>${recent.length?`<a class="resume-note panel" href="#note/${recent[0].id}"><span>${icon('note')}<span><small>최근 작성한 기록</small><strong>${esc(noteTitle(recent[0]))}</strong></span></span><span>이어서 작성하기 ${icon('arrow')}</span></a>`:''}<section class="journey panel"><div class="section-head"><div><span class="eyebrow">KEEP READING, KEEP GROWING</span><h2>매일, 쌓이는 나의 시선</h2></div><a class="text-link" href="#tracker">월별 달력 ${icon('arrow')}</a></div><div class="lifetime-stats"><div><strong>${days}</strong><span>이번 달 기록한 날</span></div><div><strong>${S.notes.filter(n=>n.type==='daily').length}</strong><span>전체 스크랩</span></div><div><strong>${S.terms.length}</strong><span>나의 경제 용어</span></div></div>${dayStrip()}<p class="micro">날짜 제한 없이 매일 기록할 수 있어요. 같은 계정으로 로그인하면 PC·모바일에서 이어집니다.</p></section><section class="home-bottom"><div><div class="section-head"><h2>최근 스크랩노트 <span class="count">${S.notes.length}</span></h2><a class="text-link" href="#notes">전체 보기 ${icon('arrow')}</a></div>${recent.length?`<div class="recent-notes">${recent.map(noteCard).join('')}</div>`:`<div class="empty-card"><span class="empty-circle">${icon('note')}</span><h3>오늘부터, 꾸준히 기록해요</h3><p>기존 기록은 설정에서 선택해 가져올 수 있어요.</p><a class="text-link accent" href="#new/daily">첫 스크랩 시작하기 ${icon('arrow')}</a></div>`}</div><div class="reading-card"><div class="eyebrow">${read?'CONTINUE READING':'START HERE'}</div><span class="reading-icon">${icon('book')}</span><h2>${read?'이어서 읽어볼까요?':'처음이라면, 가이드부터'}</h2><p>${esc(g.title)}</p><a class="button outline" href="#guide/${g.id}">${read?'이어서 읽기':'가이드북 열기'} ${icon('arrow')}</a><small>가이드북 원문 · ${g.page}쪽</small></div></section>`;
}
function guideMarkup(g,compact=false){return `<article class="guide-article ${compact?'compact':''}"><div class="source-label">가이드북 원문 · ${g.page}쪽</div><h${compact?'3':'2'}>${esc(g.bodyTitle||g.title)}</h${compact?'3':'2'}>${g.id==='reading'&&!compact?'<p class="micro">목차 명칭: 경제기사 쉽게 읽는 방법</p>':''}${g.blocks.length?`<ol class="guide-steps">${g.blocks.map((b,i)=>`<li id="step-${g.id}-${i}"><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(b[0])}</h3><p>${esc(b[1]).replace(/\n/g,'<br>')}</p></div></li>`).join('')}</ol>`:''}${g.aside?`<aside class="source-callout"><strong>${esc(g.aside[0])}</strong><p>${esc(g.aside[1]).replace(/\n/g,'<br>')}</p></aside>`:''}${g.example?exampleMarkup(g,compact):''}<div class="source-credit">템플릿·가이드라인 제공: 빠빠돈 | 경제신문 읽는 아기 아빠 (contact.ppappadon@gmail.com)</div></article>`;}
function exampleMarkup(g,compact){const ex=g.example;return `<div class="example-sheet"><div class="example-meta">날짜 ${ex.date} <span>신문 ${ex.paper}</span></div><h3>기사 제목 : ${esc(ex.title)}</h3>${DAILY_FIELDS.map(([key,en,label,req])=>`<div class="example-entry"><span>${en}</span><strong>${key==='soWhat'?'그래서 어떻게 될까':key==='thought'?'나의 생각 한 줄':label} <small>(${req?'필수':'선택'})</small></strong><p>→ ${esc(ex[key]).replace(/\n/g,'<br>')}</p></div>`).join('')}</div>`;}
function guidePage(){const g=guideBy(S.id||S.settings.reading?.guide||'rules');S.id=g.id;return `${heading('THE GUIDEBOOK','읽는 법부터, 쓰는 법까지.','가이드북 원문을 주제별로 읽고 바로 기록해 보세요.')}<div class="guide-layout"><aside class="toc panel"><div class="eyebrow">CONTENTS</div><label class="search-field">${icon('search')}<span class="sr-only">가이드북 목차와 본문 검색</span><input id="guide-search" type="search" placeholder="목차 · 본문 검색" value="${esc(S.guideQuery)}"></label><div id="guide-results">${guideResults()}</div><div class="toc-footer"><span class="source-label">현재 읽는 주제</span><strong>${g.number} / 04</strong><div class="progress-track"><i style="width:${Number(g.number)/4*100}%"></i></div></div></aside><div class="guide-content"><div class="guide-content-panel panel">${guideMarkup(g)}<div class="guide-note-actions"><div><h3>읽은 내용을 나의 언어로.</h3><p>이 주제를 참고해 스크랩노트를 작성해 보세요.</p></div><button class="button primary" data-action="new-linked" data-guide="${g.id}">${icon('plus')} 이 주제로 노트 쓰기</button></div><div class="guide-pagination">${GUIDES.map(x=>`<a href="#guide/${x.id}" class="${x.id===g.id?'selected':''}" ${x.id===g.id?'aria-current="page"':''}>${x.number}<span>${esc(x.title)}</span></a>`).join('')}</div></div><section class="related-section"><div class="section-head"><h2>이 주제에 연결된 노트</h2><a class="text-link" href="#notes?guide=${g.id}">목록에서 보기 ${icon('arrow')}</a></div>${S.notes.filter(n=>n.guide===g.id).length?`<div class="notes-grid">${sorted().filter(n=>n.guide===g.id).slice(0,4).map(noteCard).join('')}</div>`:'<p class="muted">아직 연결된 노트가 없어요. 위의 버튼으로 첫 기록을 남겨보세요.</p>'}</section></div></div>`;}
function guideResults(){const q=S.guideQuery.trim().toLowerCase();const matches=GUIDES.filter(g=>JSON.stringify(g).toLowerCase().includes(q));return matches.length?`<nav class="toc-list" aria-label="가이드북 목차">${matches.map(g=>`<a class="${g.id===S.id?'active':''}" href="#guide/${g.id}" ${g.id===S.id?'aria-current="page"':''}><span>${g.number}</span><div>${esc(g.title)}${q?`<small>${esc(guideSnippet(g,q))}</small>`:''}</div>${icon('chevron')}</a>`).join('')}</nav>`:'<p class="no-results" role="status">검색 결과가 없어요.<br>다른 단어로 검색해 보세요.</p>';}
function guideSnippet(g,q){const raw=[g.bodyTitle||g.title,...g.blocks.flat(),...(g.example?Object.values(g.example):[]),...(g.aside||[])].join(' ');const i=raw.toLowerCase().indexOf(q);return raw.slice(Math.max(0,i-15),Math.max(0,i-15)+90);}
function notesPage(){return `${heading('MY SCRAPBOOK','오늘 읽은 것, 나에게 남은 것.','매일의 스크랩과 한 주의 생각을 모아보세요.',`<div class="heading-actions"><a class="button outline" href="#new/weekly">주간 회고 쓰기</a><a class="button primary" href="#new/daily">${icon('plus')} 새 스크랩</a></div>`)}<div class="list-toolbar panel"><label class="search-field">${icon('search')}<span class="sr-only">노트 제목과 본문 검색</span><input id="note-search" type="search" placeholder="제목이나 기록한 내용으로 검색" value="${esc(S.query)}"></label><label class="filter-label">관련 주제<select id="topic-filter" aria-label="관련 주제"><option value="all">모든 주제</option>${GUIDES.map(g=>`<option value="${g.id}" ${S.filter===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}<option value="weekly" ${S.filter==='weekly'?'selected':''}>주간 회고 작성 안내</option></select></label><label class="filter-label">기록 종류<select id="type-filter" aria-label="기록 종류"><option value="all">모든 기록</option><option value="daily" ${S.typeFilter==='daily'?'selected':''}>일일 스크랩</option><option value="weekly" ${S.typeFilter==='weekly'?'selected':''}>주간 회고</option></select></label></div><div id="notes-results">${notesResults()}</div>`;}
function notesResults(){const q=S.query.trim().toLowerCase();const notes=sorted().filter(n=>(S.filter==='all'||n.guide===S.filter)&&(S.typeFilter==='all'||n.type===S.typeFilter)&&(!q||[n.title,n.what,n.why,n.soWhat,n.terms,n.thought,n.keywords,n.memorable,n.newWords,n.watch,n.nickname].join(' ').toLowerCase().includes(q)));return `<p class="results-count" role="status">${notes.length}개의 기록 <span>최근 수정한 순서</span></p>${notes.length?`<div class="notes-grid">${notes.map(noteCard).join('')}</div>`:empty(S.notes.length?'찾으시는 기록이 없어요':'첫 번째 스크랩을 시작해 보세요',S.notes.length?'검색어나 주제 필터를 바꿔보세요.':'WHAT, WHY, SO WHAT. 한 줄씩이면 충분해요.',S.notes.length?null:'새 노트 쓰기','#new/daily')}`;}
function field(key,label,value,placeholder='',extra=''){return `<label class="field"><span>${label}</span><input name="${key}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${extra}></label>`;}
function editor(){const n=S.draft;if(!n)return empty('노트를 찾을 수 없어요','삭제되었거나 다른 브라우저에 저장된 기록일 수 있어요.','노트 목록으로','#notes');const daily=n.type==='daily';const day=dayForDate(n.date);return `<div class="editor-top"><a class="text-link" href="#notes">← 노트 목록</a><div class="editor-top-actions"><span id="save-status" class="save-status ${S.status}" role="status" aria-live="polite"><i></i>${statusLabel()}</span><button class="button outline small export-trigger" data-action="export-image">인증 이미지</button><button class="icon-button" title="노트 인쇄 또는 PDF로 저장" aria-label="노트 인쇄 또는 PDF로 저장" data-action="print">${icon('print')}</button><button class="icon-button danger" title="노트 삭제" aria-label="노트 삭제" data-action="delete">${icon('trash')}</button></div></div><div class="editor-heading"><div class="eyebrow">${daily?'DAILY SCRAP':'WEEKLY REFLECTION'} <span>${daily?formatDate(n.date):weekLabel(n.weekStart||weekStart(n.date))}</span></div><h1>${daily?'오늘의 기사를, 나의 언어로.':'한 주의 기록을 돌아보며.'}</h1><p>${daily?'원문 일일 양식 · 날짜 제한 없이 기록':'원문 주간 회고 양식 · 매주 계속 기록'}</p></div><div id="save-error" class="save-error ${S.status==='error'?'':'hidden'}" role="alert">서버 동기화를 기다리고 있어요. 기기 임시 저장 여부는 위 상태를 확인해 주세요.<div><button class="button small primary" data-action="retry-save">다시 저장</button><button class="button small outline" data-action="backup">현재 내용 백업</button></div></div><div class="editor-layout ${S.referenceOpen?'':'reference-closed'}"><form id="note-form" class="note-form panel" autocomplete="off"><div class="form-top"><span class="source-label">${daily?'일일 스크랩노트':'주간 회고 · 선택 기록'}</span><button type="button" class="text-link" data-action="toggle-reference">${icon('book')} ${S.referenceOpen?'참고 화면 접기':'가이드 함께 보기'}</button></div>${daily?dailyForm(n):weeklyForm(n)}<div class="form-bottom"><span id="completion-text">${daily?(complete(n)?'필수 3칸을 작성했어요. 오픈채팅방 인증도 잊지 마세요.':'WHAT · WHY · SO WHAT은 한 줄 이상씩 작성해 주세요.'):'주간 회고는 모든 항목이 선택이에요.'}</span><button type="button" class="button outline small" data-action="retry-save">지금 저장</button></div><div class="app-notice"><strong>앱 사용 안내</strong> 초안은 기기에 먼저 저장하고 서버와 동기화합니다. 인증한 날은 기록 달력에서 직접 표시해 주세요.</div></form>${S.referenceOpen?`<aside class="reference-panel panel"><div class="reference-heading"><div><span class="eyebrow">KEEP THE GUIDE CLOSE</span><h2>쓰면서 참고해요</h2></div><button class="icon-button" data-action="toggle-reference" aria-label="참고 화면 접기">${icon('close')}</button></div><label class="field"><span>참고할 내용</span><select id="reference-select" aria-label="참고할 내용">${GUIDES.map(g=>`<option value="${g.id}" ${S.ref===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}<option value="weekly" ${S.ref==='weekly'?'selected':''}>주간 회고 작성 안내</option></select></label><div id="reference-body">${referenceBody()}</div></aside>`:''}</div><div class="print-sheet" id="print-sheet"></div>`;}
function dailyForm(n){return `<div class="form-row">${field('date','기록 날짜',n.date,'','type="date"')}${field('nickname','닉네임',n.nickname,'원문의 닉네임 칸')}</div><fieldset class="paper-picker"><legend>신문</legend>${['매일경제','한국경제'].map(p=>`<label><input type="radio" name="paper" value="${p}" ${n.paper===p?'checked':''}><span>${p}</span></label>`).join('')}</fieldset><div class="section-divider"><span>TODAY</span> 오늘의 기사</div>${field('title','기사 제목',n.title,'오늘 읽은 기사의 제목을 적어주세요.')}<div class="attachment-section"><div class="attachment-heading"><label for="article-images">기사 이미지 <span class="optional">선택</span></label><span class="micro">PNG · JPG · WebP / 장당 8MB, 최대 4장</span></div><label class="upload-zone" for="article-images">${icon('upload')}<span>기사 사진이나 캡처를 추가해 주세요</span><small>눌러서 파일 선택</small></label><input class="sr-only" id="article-images" type="file" accept="image/png,image/jpeg,image/webp" multiple><div id="attachments">${attachmentsMarkup()}</div></div><label class="recommended"><input name="recommended" type="checkbox" ${n.recommended?'checked':''}><span>추천기사로 골랐어요 <span class="optional">선택</span></span></label>${DAILY_FIELDS.map(([key,en,label,required,placeholder,guide])=>`<div class="writing-field"><div class="writing-label"><label for="field-${key}"><span class="field-en">${en}</span> <strong>${label}</strong> <span class="${required?'required':'optional'}">${required?'필수':'선택'}</span></label><button type="button" class="field-help" data-action="field-help" data-guide="${guide}" aria-label="${label} 작성 가이드 보기">${icon('book')}</button></div><textarea id="field-${key}" name="${key}" rows="${required?4:3}" placeholder="${esc(placeholder)}" aria-required="${required}" ${required?`aria-describedby="hint-${key}"`:''}>${esc(n[key])}</textarea>${required?`<small id="hint-${key}" class="micro">인증 기준: 한 줄 이상 작성 · 미작성 상태에서도 초안 저장 가능</small>`:''}</div>`).join('')}<label class="field linked-guide"><span>연결된 가이드북 <small class="optional">앱 연결 기능</small></span><select name="guide" aria-label="연결된 가이드북">${GUIDES.map(g=>`<option value="${g.id}" ${n.guide===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label><div class="note-terms-callout"><button type="button" class="button outline small" data-action="add-term">모르는 용어를 용어장에 등록</button><a class="text-link" href="#glossary">나의 용어장 보기 →</a>${S.terms.filter(t=>t.noteIds.includes(n.id)).map(t=>`<span class="badge green">${esc(t.word)}</span>`).join('')}</div><a id="linked-guide-link" class="text-link accent" href="#guide/${n.guide}">연결된 가이드북 열기 ${icon('arrow')}</a>`;}
function weeklyForm(n){const start=n.weekStart||weekStart(n.date);return `${field('weekStart','돌아볼 주의 시작일',start,'','type="date"')}<p class="micro">선택한 날짜가 속한 월요일부터 일요일까지: <span id="week-range">${weekLabel(start)}</span></p>${field('title','노트 제목 · 앱 목록 표시용',n.title,'예: 이번 주를 돌아보며')}<p class="source-callout">주간 단어장 · 주간 요약을 보며 채워보세요 (선택)</p>${WEEKLY_FIELDS.map(([key,label])=>`<div class="writing-field"><label for="field-${key}"><strong>${label}</strong> <span class="optional">선택</span></label><textarea id="field-${key}" name="${key}" rows="4" placeholder="이번 주의 생각을 남겨보세요.">${esc(n[key])}</textarea></div>`).join('')}<a class="text-link accent" href="#tracker">기록 달력에서 이번 주 돌아보기 ${icon('arrow')}</a>`;}
function attachmentsMarkup(){return `<div class="attachments-grid">${(S.draft?.attachments||[]).map((a,i)=>`<div class="attachment"><button type="button" data-action="draft-image" data-index="${i}" aria-label="${esc(a.name)} 확대"><img src="${a.data||a.url}" alt="${esc(a.name)}"></button><div><span>${esc(a.name)}</span><button type="button" class="icon-button danger" data-action="remove-image" data-index="${i}" aria-label="${esc(a.name)} 삭제">${icon('close')}</button></div></div>`).join('')}</div>`;}
function referenceBody(){return S.ref==='weekly'?weeklyGuide():`${guideMarkup(guideBy(S.ref),true)}<a class="text-link accent" href="#guide/${S.ref}">가이드북에서 자세히 보기 ${icon('arrow')}</a>`;}
function weeklyGuide(){return `<article class="guide-article compact"><div class="source-label">스크랩노트 원문 · 2, 8, 14, 20쪽</div><h3>WEEK · 한 주 돌아보기</h3><p>매주 주간 단어장 · 경제 주간 요약을 드려요. WEEK 페이지에서 한 주를 돌아봐요.</p><p>주간 단어장 · 주간 요약을 보며 채워보세요 (선택)</p><ul class="simple-list">${WEEKLY_FIELDS.map(([,l])=>`<li>${l}</li>`).join('')}</ul><div class="app-notice"><strong>앱 사용 안내</strong> 주간 단어장과 주간 요약 자체는 첨부 파일에 포함되어 있지 않아요. 받은 자료를 참고해 기록해 주세요.</div></article>`;}
function tracker(){const c=Object.values(S.settings.checks||{}).filter(Boolean).length;return `${heading('ONE DAY AT A TIME','꾸준함은, 이렇게 쌓여요.','1기 원문 일정 · 2026년 10월 26일–11월 13일. 매일의 기록은 기록 달력에서 계속해요.')}<section class="tracker-panel panel"><div class="section-head"><div><span class="source-label">스크랩노트 원문 · 21쪽</span><h2>15일 완주 체크판</h2></div><span class="tracker-total"><strong>${c}</strong> / 15</span></div><p class="source-text">인증한 날의 칸을 하나씩 채워보세요.</p><div class="tracker-days-header">${['월','화','수','목','금'].map(x=>`<span>${x}</span>`).join('')}</div>${[0,1,2].map(w=>`<div class="week-label">WEEK ${w+1}<a class="text-link" href="#new/weekly?week=${w+1}">주간 회고 쓰기 ${icon('arrow')}</a></div><div class="tracker-grid">${DAYS.slice(w*5,w*5+5).map((d,j)=>{const day=w*5+j+1,checked=S.settings.checks?.[day],notes=S.notes.filter(n=>n.type==='daily'&&n.date===d),done=notes.some(complete);return `<div class="tracker-day ${checked?'is-checked':''}"><label><input data-day="${day}" type="checkbox" ${checked?'checked':''}><span class="tracker-day-num">${day}</span><span class="tracker-day-date">${d.slice(5).replace('-','/')}</span><span class="tracker-state">${checked?'인증 체크함':'인증 후 체크'}</span></label><button class="tracker-note-link" data-action="day-note" data-date="${d}">${done?'필수 3칸 작성 ✓':notes.length?'초안 이어 쓰기':'노트 쓰기'} ${icon('chevron')}</button></div>`;}).join('')}</div>`).join('')}<div class="materials"><h3>주간 자료 받기 <span class="optional">단어장 · 주간 요약</span></h3><div>${[1,2,3].map(w=>`<label><input type="checkbox" data-material="${w}" ${S.settings.materials?.[w]?'checked':''}> ${w}주차</label>`).join('')}</div></div><div class="tracker-quote"><p>다 채운 당신은 이미 3년 갈 사람입니다</p><span class="source-label">스크랩노트 원문 · 21쪽</span></div><div class="source-callout"><strong>원문 환급 안내</strong><p>15칸을 모두 채우면 보증금 환급! (11/16~20)</p></div><div class="app-notice"><strong>앱 사용 안내</strong> 이 체크판은 본인의 인증 기록을 관리하는 용도예요. 실제 인증 확인과 환급은 챌린지 운영자 안내를 따라 주세요.</div></section><section class="completion-message"><span class="eyebrow">스크랩노트 원문 · 22쪽</span><h2>15일, 진짜 하셨네요.</h2><p>이제 16일째는 그냥 하던 대로 하시면 됩니다.</p><p class="muted">경제신문읽기 1기 완주를 축하해요!<br>완주 후기를 오픈채팅방에 남겨주세요.<br>2기 소식도 가장 먼저 알려드릴게요.</p></section>`;}
function settingsPage(){const state=storage.syncState();return `${heading('YOUR WORDS, SAFELY KEPT','어디서든 이어지는 기록.','같은 계정으로 로그인하고, PC와 모바일에서 이어 쓰세요.')}<div class="settings-grid"><section class="panel settings-card"><span class="settings-icon">${icon('lock')}</span><h2>계정별 저장 · 자동 동기화</h2><p class="account-email">${esc(S.user?.email||'')}</p><p>노트·기사 이미지·용어장·체크 상태는 로그인한 계정에 연결해 서버에 저장해요. 기기를 바꿔도 같은 계정이면 이어집니다.</p><div id="sync-detail" class="app-notice"><strong>${syncLabel()}</strong>아직 전송하지 못한 항목 ${state.pending}개 · 확인할 충돌 ${state.conflicts}개</div><button class="button outline" data-action="sync-now">지금 동기화</button><a class="text-link" href="/signout-with-chatgpt?return_to=%2F" target="_top">로그아웃</a><p class="micro">통신 실패 중인 입력은 이 기기에 임시 보관해요. 서버 저장 완료를 확인한 뒤 다른 기기에서 열어주세요. 앱을 다시 열거나 돌아왔을 때와 사용 중 약 20초마다 변경을 확인합니다.</p></section><section class="panel settings-card"><span class="settings-icon">${icon('upload')}</span><h2>이전 브라우저 기록 가져오기</h2><p>업데이트 전 이 브라우저에 있던 노트는 자동으로 업로드하지 않았어요. 계정을 확인하고 원하는 기록만 선택해 가져오세요.</p><button class="button primary" data-action="legacy-import">이전 기록 확인하기</button><p class="micro">PC와 모바일 양쪽에 기록이 있으면 각각 해당 브라우저에서 가져오세요. 이미 가져온 ID는 건너뛰어요. 같은 ID의 다른 내용을 반영하려면 백업 복원을 사용해 주세요.</p></section><section class="panel settings-card"><span class="settings-icon">${icon('download')}</span><h2>전체 기록 백업</h2><p>노트·기사 이미지·용어장·체크 상태를 JSON 파일로 보관해요. 기존 버전의 백업도 가져올 수 있어요.</p><button class="button primary" data-action="backup">${icon('download')} 백업 파일 내려받기</button><p class="micro">현재 노트 ${S.notes.length}개 · 용어 ${S.terms.length}개. 서버 이미지를 내려받으므로 인터넷 연결이 필요합니다.</p><label class="button outline" for="restore-file">${icon('upload')} 백업 파일 선택</label><input type="file" id="restore-file" class="sr-only" accept="application/json,.json"></section><section class="panel settings-card"><span class="settings-icon">${icon('book')}</span><h2>원문 자료와 1기 기록</h2><p>일일 기록과 주간 회고는 기간 제한 없이 사용할 수 있어요. 1기 일정과 원문 체크판은 별도로 보존했습니다.</p><div class="source-links"><a class="text-link" href="#challenge">1기 15일 완주 체크판 ${icon('arrow')}</a><button class="text-link" data-action="source-rules">스크랩노트 인증 규칙 보기 ${icon('arrow')}</button></div><p class="micro">템플릿·가이드라인 제공: 빠빠돈 | 경제신문 읽는 아기 아빠 · @ppappa.don (contact.ppappadon@gmail.com)<br>웹앱 제작: yukdal_t · 달력·용어장·동기화는 앱 확장 기능입니다.<br>가이드·템플릿을 다른 곳에서 사용할 때는 반드시 출처를 남겨 주세요.</p></section></div><section class="conflict-section" id="conflict-section">${conflictMarkup()}</section>`;}
function updateStatus(status){S.status=status;const el=$('#save-status');if(el){el.className=`save-status ${status}`;el.innerHTML=`<i></i>${statusLabel()}`;}$('#save-error')?.classList.toggle('hidden',status!=='error');}
function touchDraft(){S.needsSave=true;S.draft.updatedAt=Date.now();updateStatus('pending');clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft(),600);}
async function saveDraft(){clearTimeout(saveTimer);if(!S.draft||(!S.needsSave&&!S.localFailure))return true;const snapshot=structuredClone(S.draft);const job=async()=>{try{await storage.putNote(snapshot);S.localFailure=false;const i=S.notes.findIndex(n=>n.id===snapshot.id);if(i>=0)S.notes[i]=snapshot;else S.notes.push(snapshot);if(S.draft?.id===snapshot.id&&JSON.stringify(S.draft)===JSON.stringify(snapshot)){S.needsSave=false;updateStatus(storage.noteStatus(snapshot.id));}return true;}catch(e){S.localFailure=true;updateStatus('error');toast(e.message||'기기 임시 저장에도 실패했어요. 현재 내용을 백업해 주세요.');return false;}};saveQueue=saveQueue.then(job,job);return saveQueue;}
async function persistSettings(){try{await storage.putSettings(structuredClone(S.settings));return true;}catch(e){S.error='설정이나 체크 상태를 저장하지 못했어요. 백업 파일을 내려받거나 저장소를 다시 연결해 주세요.';toast(S.error);return false;}}
async function newNote(type='daily',options={}){const t=Date.now(),date=options.date||today(),start=options.week?[ '2026-10-26','2026-11-02','2026-11-09'][options.week-1]:weekStart(date);const n={id:crypto.randomUUID(),type,title:'',date:type==='weekly'?start:date,weekStart:start,nickname:S.settings.nickname||'',paper:'',guide:type==='weekly'?'weekly':options.guide||'reading',week:options.week||weekForDate(date),recommended:false,attachments:[],createdAt:t,updatedAt:t};for(const [key]of type==='weekly'?WEEKLY_FIELDS:DAILY_FIELDS)n[key]='';S.draft=n;S.needsSave=true;S.notes.push(structuredClone(n));S.ref=n.guide;S.referenceOpen=true;storage.setEditing(n.id);await saveDraft();go('note',n.id);}
async function openDay(date){const n=sorted().find(n=>n.type==='daily'&&n.date===date);if(n)go('note',n.id);else await newNote('daily',{date});}
async function confirmDialog(title,body,yes='확인',danger=false){return new Promise(resolve=>{const d=$('#dialog');d.innerHTML=`<div class="dialog-body"><h2 id="dialog-title">${esc(title)}</h2><div class="dialog-copy">${body}</div><div class="dialog-actions"><button class="button outline" data-dialog="cancel">취소</button><button class="button ${danger?'danger-fill':'primary'}" data-dialog="confirm">${esc(yes)}</button></div></div>`;d.showModal();let settled=false;const done=value=>{if(settled)return;settled=true;d.close();resolve(value);};$('[data-dialog="cancel"]',d).onclick=()=>done(false);$('[data-dialog="confirm"]',d).onclick=()=>done(true);d.oncancel=e=>{e.preventDefault();done(false);};d.onclose=()=>done(false);});}
function showImage(src,title){const d=$('#dialog');d.oncancel=null;d.onclose=null;d.innerHTML=`<div class="image-dialog"><div><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" aria-label="이미지 닫기">${icon('close')}</button></div><p class="micro">이미지 영역을 스크롤해 자세히 볼 수 있어요.</p><div class="image-scroll" tabindex="0" aria-label="확대 이미지 · 방향키로 스크롤"><img src="${src}" alt="${esc(title)}"></div></div>`;$('.icon-button',d).onclick=()=>d.close();d.showModal();}
async function deleteCurrent(){const n=S.draft;if(!n)return;const yes=await confirmDialog('이 노트를 삭제할까요?',`<p>‘${esc(noteTitle(n))}’과 첨부 이미지가 삭제됩니다.</p><p>삭제 후 되돌릴 수 없어요. 필요하면 먼저 백업해 주세요.</p>`,'삭제하기',true);if(!yes)return;clearTimeout(saveTimer);await saveQueue;try{await storage.removeNote(n.id);S.notes=S.notes.filter(x=>x.id!==n.id);S.draft=null;S.status='saved';go('notes');toast('노트를 삭제했어요.');}catch{updateStatus('error');toast('삭제하지 못했어요. 노트는 그대로 유지됩니다.');}}
async function addImages(files){if(!S.draft)return;const draft=S.draft;const selected=[...files];if(draft.attachments.length+selected.length>4){toast('이미지는 최대 4장까지 첨부할 수 있어요.');return;}for(const file of selected){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024){toast('PNG·JPG·WebP 파일을 장당 8MB 이내로 선택해 주세요.');return;}}try{const images=await Promise.all(selected.map(file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({name:file.name,data:r.result});r.onerror=reject;r.readAsDataURL(file);})));if(S.draft!==draft)return;draft.attachments.push(...images);$('#attachments').innerHTML=attachmentsMarkup();touchDraft();}catch{toast('이미지를 읽지 못했어요. 다시 선택해 주세요.');}}
async function buildBackup(){const map=new Map(S.notes.map(n=>[n.id,n]));if(S.draft)map.set(S.draft.id,S.draft);return {format:'news-scrap-backup',version:2,exportedAt:new Date().toISOString(),notes:await storage.materializeNotes([...map.values()]),terms:S.terms,settings:S.settings};}
async function downloadBackup(){try{toast('기사 이미지를 포함해 백업을 준비하고 있어요.');downloadJson(await buildBackup(),`경제신문읽기-백업-${today()}.json`);toast('백업 파일을 내려받았어요.');}catch(e){toast(e.message||'백업하지 못했어요. 인터넷 연결을 확인해 주세요.');}}
async function restoreFile(file){if(!file)return;if(file.size>100*1024*1024){toast('100MB 이하의 백업 파일을 선택해 주세요.');return;}let b;try{b=storage.validateBackup(JSON.parse(await file.text()));}catch(e){toast(e.message||'백업 파일을 읽지 못했어요.');return;}const overlaps=b.notes.filter(n=>S.notes.some(x=>x.id===n.id)).length;const yes=await confirmDialog('이 계정에 백업을 복원할까요?',`<p>저장할 계정: <strong>${esc(S.user.email)}</strong></p><p>노트 ${b.notes.length}개 · 용어 ${b.terms.length}개. 같은 ID의 노트 ${overlaps}개와 체크 상태는 백업 내용으로 바뀝니다. 다른 기기 수정이 확인되면 자동으로 덮어쓰지 않고 선택을 요청해요.</p>`,'복원하기');if(!yes)return;try{await storage.mergeBackup(b.notes,b.settings,b.terms);await refreshData();shell();toast('기기에 복원했어요. 서버 동기화 완료를 확인해 주세요.');}catch(e){toast(e.message||'복원하지 못했어요.');}}
function printNote(){const n=S.draft;if(!n)return;const daily=n.type==='daily';$('#print-sheet').innerHTML=`<div class="print-brand">경제신문읽기 1기 · 경제신문 스크랩</div><h1>${esc(noteTitle(n))}</h1><p>${daily?`${formatDate(n.date)} · ${esc(n.paper)} · ${esc(n.nickname)}`:weekLabel(n.weekStart||weekStart(n.date))}</p>${daily?`<div class="print-images">${n.attachments.map(a=>`<img src="${a.data||a.url}" alt="${esc(a.name)}">`).join('')}</div>${n.recommended?'<p>☑ 추천기사로 골랐어요</p>':''}`:''}${(daily?DAILY_FIELDS.map(([k,en,l])=>[k,`${en} · ${l}`]):WEEKLY_FIELDS).map(([k,l])=>`<section><h2>${esc(l)}</h2><p>${esc(n[k]).replace(/\n/g,'<br>')||' '}</p></section>`).join('')}<footer>템플릿·가이드라인: 빠빠돈 (contact.ppappadon@gmail.com) · 웹앱 제작: yukdal_t</footer>`;printTitle=document.title;document.title=noteTitle(n);const imgs=[...$('#print-sheet').querySelectorAll('img')];Promise.all(imgs.map(im=>im.decode().catch(()=>{}))).then(()=>window.print());}
window.addEventListener('afterprint',()=>{if(printTitle)document.title=printTitle;});
function bindPage(){
 $('#guide-search')?.addEventListener('input',e=>{S.guideQuery=e.target.value;$('#guide-results').innerHTML=guideResults();});
 $('#note-search')?.addEventListener('input',e=>{S.query=e.target.value;$('#notes-results').innerHTML=notesResults();});
 $('#topic-filter')?.addEventListener('change',e=>{S.filter=e.target.value;$('#notes-results').innerHTML=notesResults();});
 $('#type-filter')?.addEventListener('change',e=>{S.typeFilter=e.target.value;$('#notes-results').innerHTML=notesResults();});
 $('#reference-select')?.addEventListener('change',e=>{S.ref=e.target.value;$('#reference-body').innerHTML=referenceBody();});
 $('#restore-file')?.addEventListener('change',e=>restoreFile(e.target.files[0]));
 $('#article-images')?.addEventListener('change',e=>{addImages(e.target.files);e.target.value='';});
 $('#note-form')?.addEventListener('submit',e=>e.preventDefault());
 $('#note-form')?.addEventListener('input',e=>{const el=e.target;if(!el.name||!S.draft)return;S.draft[el.name]=el.type==='checkbox'?el.checked:el.name==='week'?Number(el.value):el.value;if(el.name==='date'&&validDate(el.value)){S.draft.week=weekForDate(el.value);S.draft.weekStart=weekStart(el.value);}if(el.name==='weekStart'&&validDate(el.value)){S.draft.weekStart=weekStart(el.value);S.draft.date=S.draft.weekStart;$('#week-range').textContent=weekLabel(S.draft.weekStart);}if(el.name==='guide')$('#linked-guide-link').href='#guide/'+el.value;const completed=$('#completion-text');if(completed&&S.draft.type==='daily')completed.textContent=complete(S.draft)?'필수 3칸을 작성했어요. 오픈채팅방 인증도 잊지 마세요.':'WHAT · WHY · SO WHAT은 한 줄 이상씩 작성해 주세요.';touchDraft();});
 if(S.route==='settings'&&navigator.storage?.estimate)navigator.storage.estimate().then(e=>{const el=$('#storage-info');if(el)el.textContent=`브라우저 저장 사용량 약 ${((e.usage||0)/1024/1024).toFixed(1)}MB · 남은 공간 약 ${Math.floor(((e.quota||0)-(e.usage||0))/1024/1024)}MB`;}).catch(()=>{if($('#storage-info'))$('#storage-info').textContent='저장 공간 정보를 확인할 수 없어요.';});
}
app.addEventListener('change',async e=>{const el=e.target;if(el.dataset.day){const key=el.dataset.day;S.settings.checks={...S.settings.checks,[key]:el.checked};S.settings.certified={...S.settings.certified,[DAYS[Number(key)-1]]:el.checked};await persistSettings();shell();}if(el.dataset.material){S.settings.materials={...S.settings.materials,[el.dataset.material]:el.checked};await persistSettings();toast('주간 자료 수령 상태를 저장했어요.');}});
app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='qa-failure'&&QA){qaFail=!qaFail;storage.setTestFailure(qaFail);b.textContent=qaFail?'저장 실패 재현 끄기':'저장 실패 재현 켜기';$('.qa-controls [role=status]').textContent=qaFail?'저장 실패 재현 중':'정상 저장 모드';}
 if(action==='day-note')await openDay(b.dataset.date);
 if(action==='new-linked')await newNote('daily',{guide:b.dataset.guide});
 if(action==='retry-save'){const ok=await saveDraft();if(ok){await storage.syncNow();toast(storage.noteStatus(S.draft?.id)==='saved'?'서버에 저장했어요.':'입력은 임시 보관 중이에요. 동기화 상태를 확인해 주세요.');}}
 if(action==='delete')await deleteCurrent();
 if(action==='backup')await downloadBackup();
 if(action==='print')printNote();
 if(action==='image')showImage(b.dataset.src,b.dataset.title);
 if(action==='draft-image'){const a=S.draft.attachments[Number(b.dataset.index)];showImage(a.data||a.url,a.name);}
 if(action==='remove-image'){const a=S.draft.attachments[Number(b.dataset.index)];if(await confirmDialog('기사 이미지를 삭제할까요?',`<p>${esc(a.name)}</p>`,'삭제하기',true)){S.draft.attachments.splice(Number(b.dataset.index),1);$('#attachments').innerHTML=attachmentsMarkup();touchDraft();}}
 if(action==='toggle-reference'){S.referenceOpen=!S.referenceOpen;shell();}
 if(action==='field-help'){S.ref=b.dataset.guide;S.referenceOpen=true;shell();$('.reference-panel')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
 if(action==='source-rules')await confirmDialog('경제신문읽기 인증 규칙',`<span class="source-label">스크랩노트 원문 · 2쪽</span><ol class="simple-list">${SOURCE_RULES.map(r=>`<li>${r}</li>`).join('')}</ol><p>추천기사 체크 · 모르는 용어 · 내 생각 한 줄은 쓰고 싶을 때만 써도 돼요.</p><p>매주 주간 단어장 · 경제 주간 요약을 드려요. WEEK 페이지에서 한 주를 돌아봐요.</p>`,'확인');
 if(action==='reconnect'){try{await storage.openStore();S.ready=true;const current=new Map((await storage.allNotes()).map(n=>[n.id,n]));for(const n of S.notes)if(!current.has(n.id)||current.get(n.id).updatedAt<n.updatedAt)current.set(n.id,n);S.notes=[...current.values()];S.error='';if(S.draft)await saveDraft();await persistSettings();shell();toast('저장소에 다시 연결했어요.');}catch{toast('저장소에 연결하지 못했어요. 입력 내용을 백업해 주세요.');}}
});
let routing=false,reroute=false;
async function render(){if(!S.ready)return;if(routing){reroute=true;return;}routing=true;const oldRoute=S.route,oldId=S.id;
 try{
  if(S.draft){const ok=await saveDraft();if(!ok){const yes=await confirmDialog('아직 저장되지 않은 내용이 있어요.','<p>현재 화면을 유지하면 다시 저장하거나 백업할 수 있어요. 화면을 이동하면 저장되지 않은 입력 내용이 사라질 수 있습니다.</p>','그래도 이동하기');if(!yes){history.replaceState(null,'',routeLink(oldRoute,oldId));return;}}}
  const raw=location.hash.slice(1)||'home';const [path,query]=raw.split('?');const [route,id]=path.split('/');const params=new URLSearchParams(query);
  if(route==='new'){await newNote(id==='weekly'?'weekly':'daily',{week:Number(params.get('week'))||undefined,date:params.get('date')||undefined});return;}
  S.route=route;S.id=id?decodeURIComponent(id):'';
  if(route==='notes'&&params.has('guide'))S.filter=params.get('guide');
  if(route==='note'){const n=S.notes.find(n=>n.id===S.id);S.draft=n?structuredClone(n):null;S.ref=S.draft?.guide||'reading';S.referenceOpen=true;S.status=storage.noteStatus(S.id);S.needsSave=false;}else S.draft=null;
  storage.setEditing(S.draft?.id||'');
  shell();window.scrollTo(0,0);
  if(route==='guide'){
   const saved=S.settings.reading;const prior=oldRoute!=='guide'&&saved?.guide===S.id?saved.scroll:0;
   S.settings.reading={guide:S.id,scroll:prior||0,at:Date.now()};persistSettings();
   if(prior)requestAnimationFrame(()=>window.scrollTo(0,prior));
  }
  if(oldRoute!==route)$('#main')?.focus({preventScroll:true});
 }finally{routing=false;if(reroute){reroute=false;render();}}
}
window.addEventListener('hashchange',render);
window.addEventListener('scroll',()=>{if(S.route!=='guide')return;const guide=S.id,scroll=window.scrollY;S.settings.reading={guide,scroll,at:Date.now()};clearTimeout(readTimer);readTimer=setTimeout(()=>persistSettings(),400);},{passive:true});
window.addEventListener('beforeunload',e=>{if(S.draft&&(S.needsSave||S.localFailure)){saveDraft();e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&S.draft&&S.status!=='saved')saveDraft();});
async function init(){try{await storage.openStore();S.user=storage.currentUser();await refreshData();S.ready=true;storage.subscribe(onSync);await render();onSync();}catch(e){loginScreen(e.message);}}
// Explicitly opt in to test hooks on a local QA URL; production has no hooks.
if(location.hostname==='127.0.0.1'&&new URLSearchParams(location.search).has('qa'))Object.defineProperty(window,'__newsScrapTest',{value:{failWrites:storage.setTestFailure,snapshot:()=>structuredClone({notes:S.notes,settings:S.settings,draft:S.draft,status:S.status}),validateBackup:storage.validateBackup,save:saveDraft}});
function syncLabel(){const st=storage.syncState();return ({saved:'동기화 완료',local:'기기에 저장 · 전송 대기',saving:'동기화 중…',conflict:'변경 내용 확인 필요',error:'동기화 대기',account:'계정 확인 필요'})[st.status]||'동기화 확인 중';}
function syncAlert(){const st=storage.syncState();if(st.conflicts)return `<div class="sync-warning" role="status">다른 기기에서 변경한 기록 ${st.conflicts}개가 있어요. 덮어쓰기 전에 확인해 주세요. <a href="#settings">변경 내용 확인 →</a></div>`;if(st.error)return `<div class="sync-warning" role="status">${esc(st.error)} 입력은 기기에 임시 보관됩니다. <button data-action="sync-now">다시 동기화</button></div>`;return '';}
async function refreshData(){[S.notes,S.settings,S.terms]=await Promise.all([storage.allNotes(),storage.getSettings(),storage.allTerms()]);}
let refreshing=false;
async function onSync(){if(!S.ready||refreshing)return;refreshing=true;try{const st=storage.syncState();if(st.status==='account'){loginScreen('로그인 계정이 변경되었어요. 새로고침한 뒤 계정을 확인해 주세요.');return;}const old=JSON.stringify([S.notes,S.settings,S.terms]);await refreshData();if(S.draft&&!S.needsSave&&!S.localFailure){const current=S.notes.find(n=>n.id===S.draft.id);if(current?.updatedAt===S.draft.updatedAt)S.draft.attachments=current.attachments;updateStatus(storage.noteStatus(S.draft.id));}const changed=old!==JSON.stringify([S.notes,S.settings,S.terms]);if(changed&&['home','notes','tracker','challenge','glossary'].includes(S.route)&&!$('#dialog').open){const focus=document.activeElement;if(!['INPUT','TEXTAREA','SELECT'].includes(focus?.tagName))shell();else if(S.route==='notes'&&$('#notes-results'))$('#notes-results').innerHTML=notesResults();else if(S.route==='glossary'&&$('#terms-results'))$('#terms-results').innerHTML=glossaryResults();}if($('#sync-pill'))$('#sync-pill').textContent=syncLabel();if($('#sync-alert'))$('#sync-alert').innerHTML=syncAlert();if($('#sync-detail'))$('#sync-detail').innerHTML=`<strong>${syncLabel()}</strong>전송 대기 ${st.pending}개 · 변경 확인 ${st.conflicts}개`;if($('#conflict-section')&&!$('#dialog').open)$('#conflict-section').innerHTML=conflictMarkup();}finally{refreshing=false;}}
function loginScreen(message){S.ready=false;storage.setEditing('');app.innerHTML=`<main class="login-screen"><a class="brand" href="/">경제신문읽기</a><div class="panel"><span class="eyebrow">YOUR PERSONAL READING SPACE</span><h1>나의 계정으로, 이어 쓰세요.</h1><p>${esc(message||'계정을 확인하고 기록을 불러옵니다.')}</p><a class="button primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">ChatGPT로 로그인</a><button class="button outline" onclick="location.reload()">다시 확인</button><p class="micro">기존 기록은 로그인 후 설정에서 직접 선택해 가져올 수 있어요.<br>주 사용 계정으로 로그인해 주세요. PC와 모바일에서 같은 계정을 사용해야 연동됩니다.</p></div></main>`;}
function calendarPage(){const [year,month]=S.month.split('-').map(Number),first=S.month+'-01',offset=(new Date(first+'T12:00:00').getDay()+6)%7,last=new Date(year,month,0).getDate(),cells=Math.ceil((last+offset)/7)*7;const notes=S.notes.filter(n=>n.type==='daily'&&n.date.startsWith(S.month));const dayNotes=sorted().filter(n=>n.date===S.selectedDate&&n.type==='daily');const certified=S.settings.certified?.[S.selectedDate]===true;
 return `${heading('A MONTH OF SMALL INSIGHTS','하루씩, 오래도록.','기간 제한 없이 기록하고 월별로 돌아보세요.',`<a class="button outline" href="#challenge">1기 원문 체크판</a>`)}<section class="calendar-panel panel"><div class="calendar-toolbar"><div class="month-controls"><button class="icon-button" data-action="month-prev" aria-label="이전 달">←</button><label><span class="sr-only">기록을 볼 월</span><input id="month-picker" type="month" min="1900-01" max="2200-12" value="${S.month}"></label><button class="icon-button" data-action="month-next" aria-label="다음 달">→</button></div><button class="button outline small" data-action="month-today">이번 달</button></div><div class="calendar-summary"><span><strong>${new Set(notes.map(n=>n.date)).size}</strong>일 기록</span><span>스크랩 ${notes.length}개</span><span>필수 항목 작성 ${notes.filter(complete).length}개</span></div><div class="calendar-weekdays">${['월','화','수','목','금','토','일'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:cells},(_,i)=>{const date=addDays(first,i-offset),items=notes.filter(n=>n.date===date),outside=!date.startsWith(S.month),check=S.settings.certified?.[date];return `<button class="calendar-cell ${outside?'outside':''} ${date===today()?'is-today':''} ${date===S.selectedDate?'is-selected':''}" data-action="calendar-day" data-date="${date}" aria-label="${formatDate(date)} 스크랩 ${items.length}개${check?' 인증 체크함':''}" aria-pressed="${date===S.selectedDate}"><span class="calendar-number">${Number(date.slice(8))}</span>${items.length?`<span class="calendar-note-count">${items.length}<span class="calendar-note-label">개 기록</span></span>`:'<span class="calendar-note-count empty-count">·</span>'}${check?'<span class="calendar-cert" aria-hidden="true">✓</span>':''}</button>`;}).join('')}</div><p class="micro">점과 숫자는 작성한 노트, ✓는 직접 체크한 인증 기록이에요.</p></section><section class="selected-day panel"><div class="section-head"><div><span class="eyebrow">DAILY RECORDS</span><h2>${formatDate(S.selectedDate)}</h2></div><button class="button primary small" data-action="new-on-date" data-date="${S.selectedDate}">${icon('plus')} 이 날짜에 쓰기</button></div><label class="calendar-certified"><input type="checkbox" data-certified="${S.selectedDate}" ${certified?'checked':''}> 이 날짜의 인증을 직접 완료했어요</label>${dayNotes.length?`<div class="notes-grid">${dayNotes.map(noteCard).join('')}</div>`:'<p class="muted">아직 기록이 없어요. 날짜를 골라 과거 기록도 남길 수 있어요.</p>'}<div class="calendar-weekly"><a class="text-link accent" href="#new/weekly?date=${S.selectedDate}">이 날짜가 속한 주의 회고 쓰기 ${icon('arrow')}</a></div></section>`;
}
function glossaryPage(){return `${heading('MY ECONOMIC DICTIONARY','새로 안 단어, 나의 언어로.','노트에서 만난 용어를 모으고 복습하세요.',`<button class="button primary" data-action="add-term">${icon('plus')} 용어 등록</button>`)}<div class="list-toolbar panel"><label class="search-field">${icon('search')}<span class="sr-only">용어와 뜻 검색</span><input id="term-search" type="search" placeholder="용어나 뜻으로 검색" value="${esc(S.termQuery)}"></label><label class="filter-label">복습 상태<select id="term-filter" aria-label="복습 상태"><option value="all">모든 용어</option><option value="review" ${S.termFilter==='review'?'selected':''}>복습 필요</option><option value="familiar" ${S.termFilter==='familiar'?'selected':''}>익숙해짐</option></select></label></div><div id="terms-results">${glossaryResults()}</div>`;}
function glossaryResults(){const q=S.termQuery.trim().toLowerCase(),terms=[...S.terms].filter(t=>(S.termFilter==='all'||t.status===S.termFilter)&&(!q||(t.word+' '+t.definition).toLowerCase().includes(q))).sort((a,b)=>b.updatedAt-a.updatedAt);return `<p class="results-count" role="status">${terms.length}개의 용어</p>${terms.length?`<div class="terms-grid">${terms.map(t=>`<article class="term-card panel"><div class="section-head"><h2>${esc(t.word)}</h2><span class="badge ${t.status==='familiar'?'green':''}">${t.status==='familiar'?'익숙해짐':'복습 필요'}</span></div><p class="term-definition">${esc(t.definition||'아직 뜻을 기록하지 않았어요.').replace(/\n/g,'<br>')}</p><div class="term-source-links">${t.noteIds.map(id=>{const n=S.notes.find(n=>n.id===id);return n?`<a class="text-link" href="#note/${id}">${icon('note')}${esc(noteTitle(n))}</a>`:'';}).join('')}</div><div class="term-actions"><button class="text-link accent" data-action="review-term" data-id="${t.id}">${t.status==='familiar'?'다시 복습하기':'익숙해졌어요 ✓'}</button><button class="icon-button" data-action="edit-term" data-id="${t.id}" aria-label="${esc(t.word)} 수정">${icon('note')}</button><button class="icon-button danger" data-action="delete-term" data-id="${t.id}" aria-label="${esc(t.word)} 삭제">${icon('trash')}</button></div></article>`).join('')}</div>`:empty(S.terms.length?'찾는 용어가 없어요':'오늘 만난 첫 용어를 등록해 보세요',S.terms.length?'검색어나 복습 상태를 바꿔보세요.':'노트의 자유 입력 내용은 그대로 두고, 필요한 용어만 등록할 수 있어요.')}`;}
function termDialog(id='',sourceNote=''){const existing=S.terms.find(t=>t.id===id),source=S.draft?.id===sourceNote?S.draft:S.notes.find(n=>n.id===sourceNote);const d=$('#dialog');d.oncancel=null;d.onclose=null;d.innerHTML=`<div class="dialog-body term-dialog"><h2 id="dialog-title">${existing?'용어 수정':'나의 용어장에 등록'}</h2>${source?.terms?`<details class="source-callout"><summary>노트에 적어둔 모르는 용어 참고</summary><p>${esc(source.terms).replace(/\n/g,'<br>')}</p></details>`:''}<form id="term-form">${field('word','용어 · 필수',existing?.word||'','예: 용적률','required maxlength="200"') }<label class="field"><span>뜻 · 나의 설명</span><textarea name="definition" rows="5" maxlength="20000" placeholder="내가 이해한 뜻을 기록해 보세요.">${esc(existing?.definition||'')}</textarea></label><label class="field"><span>복습 상태</span><select name="status" aria-label="복습 상태"><option value="review">복습 필요</option><option value="familiar" ${existing?.status==='familiar'?'selected':''}>익숙해짐</option></select></label><div id="term-feedback" role="status"></div><div class="dialog-actions"><button class="button outline" type="button" id="term-cancel">취소</button><button class="button primary" type="submit">저장하기</button></div></form></div>`;$('#term-cancel',d).onclick=()=>d.close();$('#term-form',d).onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,word=form.elements.word.value.trim(),definition=form.elements.definition.value,status=form.elements.status.value;if(!word)return;const dup=S.terms.find(t=>t.id!==id&&normalizeWord(t.word)===normalizeWord(word));const write=async t=>{try{await storage.putTerm(t);if(existing&&dup&&existing.id!==dup.id)await storage.removeTerm(existing.id);await refreshData();d.close();if(['glossary','note'].includes(S.route))shell();toast('기기에 저장했어요. 동기화 후 다른 기기에서도 볼 수 있어요.');}catch(error){$('#term-feedback',d).textContent=error.message;}};if(dup){$('#term-feedback',d).innerHTML=`<p>‘${esc(dup.word)}’이 이미 있어요. 기존 뜻을 유지하고 이 노트의 연결을 추가할 수 있어요. 기존 뜻이 비어 있으면 입력한 뜻을 사용합니다.</p><button type="button" class="button outline small" id="merge-term">기존 용어에 연결하기</button>`;$('#merge-term',d).onclick=()=>write({...dup,definition:dup.definition||definition,noteIds:[...new Set([...dup.noteIds,...(existing?.noteIds||[]),...(sourceNote?[sourceNote]:[])])],updatedAt:Date.now()});return;}await write({id:existing?.id||crypto.randomUUID(),word,definition,status,noteIds:[...new Set([...(existing?.noteIds||[]),...(sourceNote?[sourceNote]:[])])],createdAt:existing?.createdAt||Date.now(),updatedAt:Date.now()});};d.showModal();}
function conflictText(r){if(r.deleted)return '삭제된 기록';if(r.kind==='setting')return JSON.stringify(r.data,null,2);const x={...r.data};if(x.attachments)x.attachments=`기사 이미지 ${x.attachments.length}장`;return Object.entries(x).filter(([k])=>!['id','guide','createdAt','updatedAt'].includes(k)).map(([k,v])=>`${k}: ${Array.isArray(v)?v.join(', '):v}`).join('\n');}
function conflictMarkup(){const list=storage.conflicts();if(!list.length)return '';return `<div class="section-head"><h2>다른 기기 변경 내용 확인</h2></div><p class="muted">자동으로 덮어쓰지 않았어요. 내용을 비교하고 보관할 방법을 선택해 주세요.</p>${list.map(r=>`<article class="panel conflict-card"><h3>${esc(r.data?.title||r.data?.word||r.id)}</h3><div class="conflict-versions"><div><strong>이 기기에 있는 내용</strong><pre>${esc(conflictText(r))}</pre></div><div><strong>서버의 다른 내용</strong><pre>${esc(conflictText(r.conflict))}</pre></div></div><div class="conflict-actions"><button class="button outline small" data-action="resolve-conflict" data-id="${r.id}" data-choice="local">이 기기 내용 저장</button><button class="button outline small" data-action="resolve-conflict" data-id="${r.id}" data-choice="remote">서버 내용 사용</button>${r.kind!=='setting'&&r.data?`<button class="button primary small" data-action="resolve-conflict" data-id="${r.id}" data-choice="both">둘 다 보관</button>`:''}</div></article>`).join('')}`;}
function downloadJson(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function legacyImport(){let old;try{old=await storage.readLegacy();}catch{toast('이전 기록을 읽지 못했어요. 기존 백업 파일로 복원해 주세요.');return;}if(!old||!old.notes.length){toast('이 브라우저에 이전 버전의 노트가 없어요. 기록이 있던 브라우저에서 열거나 백업 파일을 복원해 주세요.');return;}const d=$('#dialog');d.oncancel=null;d.onclose=null;d.innerHTML=`<div class="dialog-body legacy-dialog"><h2 id="dialog-title">이전 기록을 이 계정으로 가져오기</h2><p>저장할 계정: <strong>${esc(S.user.email)}</strong></p><p class="micro">먼저 백업을 보관한 뒤 원하는 노트에 체크해 주세요. 계정이 맞지 않으면 취소하고 다시 로그인하세요.</p><button class="button outline small" id="legacy-backup">이전 기록 먼저 백업</button><div class="legacy-list">${old.notes.map(n=>`<label><input type="checkbox" name="legacy-note" value="${esc(n.id)}" ${S.notes.some(x=>x.id===n.id)?'disabled':''}><span>${esc(noteTitle(n))}<small>${esc(n.date)} ${S.notes.some(x=>x.id===n.id)?'· 이미 가져옴':''}</small></span></label>`).join('')}</div><label class="calendar-certified"><input type="checkbox" id="legacy-settings">1기 체크판·자료 수령·읽던 위치도 가져오기</label><p id="legacy-feedback" role="status"></p><div class="dialog-actions"><button class="button outline" id="legacy-cancel">취소</button><button class="button primary" id="legacy-confirm">선택한 기록 가져오기</button></div></div>`;$('#legacy-backup',d).onclick=()=>downloadJson({format:'news-scrap-backup',version:1,exportedAt:new Date().toISOString(),notes:old.notes,settings:old.settings},`경제신문읽기-이전기록-${today()}.json`);$('#legacy-cancel',d).onclick=()=>d.close();$('#legacy-confirm',d).onclick=async()=>{const ids=[...d.querySelectorAll('[name=legacy-note]:checked')].map(x=>x.value);if(!ids.length){$('#legacy-feedback',d).textContent='가져올 노트를 한 개 이상 선택해 주세요.';return;}try{const backup=storage.validateBackup({format:'news-scrap-backup',version:1,notes:old.notes.filter(n=>ids.includes(n.id)),settings:$('#legacy-settings',d).checked?old.settings:{}});const currentSettings=await storage.getSettings();await storage.mergeBackup(backup.notes,$('#legacy-settings',d).checked?{...currentSettings,...backup.settings}:currentSettings);await refreshData();d.close();shell();toast('선택한 기록을 기기에 가져왔어요. 서버 동기화 완료를 확인해 주세요.');}catch(e){$('#legacy-feedback',d).textContent=e.message;}};d.showModal();}
function bindFeatures(){
 $('#month-picker')?.addEventListener('change',e=>{if(/^\d{4}-(0[1-9]|1[012])$/.test(e.target.value)){S.month=e.target.value;S.selectedDate=S.month+'-01';shell();}});
 $('#term-search')?.addEventListener('input',e=>{S.termQuery=e.target.value;$('#terms-results').innerHTML=glossaryResults();});
 $('#term-filter')?.addEventListener('change',e=>{S.termFilter=e.target.value;$('#terms-results').innerHTML=glossaryResults();});
}
app.addEventListener('change',async e=>{if(e.target.dataset.certified){S.settings.certified={...S.settings.certified,[e.target.dataset.certified]:e.target.checked};const day=DAYS.indexOf(e.target.dataset.certified)+1;if(day)S.settings.checks={...S.settings.checks,[day]:e.target.checked};await persistSettings();}});
app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{
 if(b.dataset.action==='sync-now'){if(S.draft)await saveDraft();await storage.syncNow();await onSync();toast(syncLabel());}
 if(b.dataset.action==='calendar-day'){S.selectedDate=b.dataset.date;S.month=b.dataset.date.slice(0,7);if(S.route!=='tracker')go('tracker');else shell();}
 if(b.dataset.action==='new-on-date')await newNote('daily',{date:b.dataset.date});
 if(b.dataset.action==='month-today'){S.month=today().slice(0,7);S.selectedDate=today();shell();}
 if(['month-prev','month-next'].includes(b.dataset.action)){const date=new Date(S.month+'-15T12:00:00Z');date.setUTCMonth(date.getUTCMonth()+(b.dataset.action==='month-prev'?-1:1));S.month=date.toISOString().slice(0,7);S.selectedDate=S.month+'-01';shell();}
 if(b.dataset.action==='export-image'){await saveDraft();const exported=structuredClone(S.draft);const terms=S.terms.filter(t=>t.noteIds.includes(exported.id)).map(t=>t.word+' : '+t.definition);exported.terms=[exported.terms,...terms].filter(Boolean).join('\n');await openImageExport($('#dialog'),exported,esc);}
 if(b.dataset.action==='add-term'){if(S.draft)await saveDraft();termDialog('',S.draft?.id||'');}
 if(b.dataset.action==='edit-term')termDialog(b.dataset.id);
 if(b.dataset.action==='review-term'){const t=S.terms.find(t=>t.id===b.dataset.id);await storage.putTerm({...t,status:t.status==='familiar'?'review':'familiar',updatedAt:Date.now()});await refreshData();shell();}
 if(b.dataset.action==='delete-term'){const t=S.terms.find(t=>t.id===b.dataset.id);if(await confirmDialog('이 용어를 삭제할까요?',`<p>${esc(t.word)} · 연결된 노트의 원래 기록은 유지됩니다.</p>`,'삭제하기',true)){await storage.removeTerm(t.id);await refreshData();shell();}}
 if(b.dataset.action==='legacy-import')await legacyImport();
 if(b.dataset.action==='resolve-conflict'){if(S.draft)await saveDraft();await storage.resolveConflict(b.dataset.id,b.dataset.choice);await refreshData();if(S.draft)S.draft=structuredClone(S.notes.find(n=>n.id===S.id)||null);shell();toast('선택한 방법으로 처리했어요. 동기화 상태를 확인해 주세요.');}
 }catch(error){toast(error.message||'작업을 마치지 못했어요. 다시 시도해 주세요.');}});
init();
